-- Marketing pages aligned from live site copy in content.ts
BEGIN;
DELETE FROM public.marketing_pages WHERE slug = 'new-home';
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('ec4792a6-d5e1-4527-a0ad-f376b3d7a095', 'home', 'Home', '{"seo":{"title":"Twentyone06, Design by the People, for the People","description":"Twentyone06 creative design studio, interiors, branding, and bold hospitality experiences across Dubai and the UAE.","keywords":["interior design company Dubai","interior design studio Dubai","interior design studio Firm","full-service interior design agency Dubai","award winning interior design Dubai","hospitality interior design Dubai","restaurant interior design Dubai","hotel interior design Dubai","commercial interior design Dubai","retail interior design Dubai","F&B interior design Dubai","branding studio Dubai","interior design management Dubai","design strategy consultancy Dubai","brand identity design Dubai","space planning Dubai","concept design hospitality UAE","interior branding agency Dubai","best interior design studio Dubai","hospitality design firm UAE","luxury hotel interior design Dubai","F&B restaurant design UAE","design firm for developers Dubai","interior design company Saudi Arabia","interior design studio Riyadh","hospitality interior design Jeddah","commercial interior design Saudi Arabia","interior design firm Kuwait","hospitality design GCC","full service interior design Middle East","design studio UAE GCC"]},"hero":{"eyebrow":"Creative Design Studio","titleLines":[{"before":"Design by the ","accent":"People."},{"before":"For the ","accent":"People."}],"description":"Dubai''s multi-award winning\ninterior design and branding studio.","sectors":"Hospitality  ·  F&B  ·  Hotels  ·  Retail  ·  Commercial","ctas":[{"label":"See Our Work","to":"/projects"},{"label":"Let''s Talk","to":"/contact"}],"image":"https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1920","rail":[{"label":"Years of Craft","value":"10+"},{"label":"Projects Delivered","value":"50+"},{"label":"Clients Worldwide","value":"50K+"}]},"philosophy":{"eyebrow":"The Twentyone06 Philosophy","title":["We Design For","People."],"body":"Every space we design starts with a question: what does this need to do for the people using it? Not aesthetically. Commercially. Experientially. Operationally. In hospitality, F&B, and retail, the design is not decoration. It is the reason guests stay longer, come back, and bring others. We design with that understanding at the centre of every brief, bold where it counts, precise where it matters, and always in service of the people the space is built for.","cta":"More About Us","ctaTo":"/about","image":"https://images.pexels.com/photos/2379005/pexels-photo-2379005.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1200"},"services":{"eyebrow":"What We Do","title":"Services","cta":"View All Services","ctaTo":"/services","items":[{"index":"01","slug":"interior-design","title":"Interior Design","description":"Multi-award winning interior design for hospitality, F&B, hotel, retail, and commercial spaces across Dubai and the GCC.","detail":"TwentyOne06 is a multi-award winning interior design firm in Dubai, specialising in hospitality, F&B, hotel, retail, and commercial spaces. 40+ projects across Dubai, the UAE, and the GCC, from Michelin-starred restaurants to international hotel groups. We cover every stage, every sector, and every detail from the first brief to the final handover.","bullets":["Hospitality and F&B interior design, Dubai and UAE","Hotel and resort interior design, GCC","Retail and commercial space design","Restaurant and bar interior design","Concept development and spatial planning","Construction documentation and on-site supervision"],"cta":"Let''s Design Your Space","image":"/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-brand-identity-design-by-twentyone06-scaled-1-b400306b.png"},{"index":"02","slug":"branding","title":"Branding","description":"Branding strategies from logos and signage to environmental graphics, every touchpoint with a consistent voice.","detail":"Your space tells a story, and we make sure it tells the right one. We develop branding strategies that extend from logos and signage to environmental graphics and wayfinding systems, giving every touchpoint a consistent, distinctive voice.","bullets":["Brand identity and visual systems","Logo design and naming strategy","Signage and environmental graphics","Brand guidelines and asset libraries","Brand refresh and repositioning"],"cta":"Let''s Build Your Brand","image":"/projects/cheese-board-by-grandiose-cheese-board-by-twentyone06-3-1-05ccbf6c.png"},{"index":"03","slug":"design-management","title":"Design Management","description":"Local market expertise connecting client, designer, and contractor under one clear direction.","detail":"Excellence in execution requires meticulous oversight. We add local market expertise to your team, connecting client, designer, and contractor under one clear direction, and bringing the leadership and accountability your project needs to be delivered without compromising on quality or creativity.","bullets":["Material selection and specification","Design coordination and quality control","Value engineering without compromising design intent","Local market and supplier knowledge, UAE and GCC","Cost and programme alignment"],"cta":"Let''s Manage Your Design","image":"/projects/tokyo-arabia-tokyo-arabia-alurubah-branch-21-scaled-4ecf8607.jpg"},{"index":"04","slug":"design-strategy","title":"Design Strategy And Operations","description":"Define what a space must achieve commercially, experientially, and operationally before a single line is drawn.","detail":"Before a single line is drawn, the most important decisions are already being made. TwentyOne06''s Design Strategy and Operations service helps hospitality and F&B operators across Dubai, the UAE, and the GCC, define what their space needs to achieve, commercially, experientially, and operationally, before the design process begins. From space programming and guest experience mapping to revenue-driven design frameworks, we ensure creative ambition and business reality stay aligned from day one.","bullets":["Pre-design strategic consultation, UAE and GCC","Space programming and commercial viability","Guest experience mapping and journey design","Revenue-driven design frameworks","Post-occupancy review and optimisation"],"cta":"Plan With Us","image":"/services/design-strategy.jpg"}]},"projects":{"eyebrow":"Our Work","title":"Our Creations","cta":"Explore all projects","ctaTo":"/projects"},"clients":{"eyebrow":"Trusted by Visionaries"},"testimonialSection":{"title":"Our Testimonials"},"journal":{"title":"We Have News!","description":"Our take on project reveals, award wins, and the design conversations worth the read.","cta":"View All Articles","ctaTo":"/journal","tabs":[{"id":"whats-new","label":"What''s New","description":"Studio updates, project features, and news from TwentyOne06."},{"id":"trend-reports","label":"Trend Reports","description":"Industry research and design insights from our team."}]},"testimonials":[{"quote":"The team exceeded our expectations with their exceptional design and development skills. They truly understood our vision and brought it to life. We couldn’t be happier with the final product.","name":"Steven Batchelor Frios","role":"Managing Director . UN!Que Project Solutions","image":""},{"quote":"We had the pleasure of working with TwentyOne06 on an office project in Al Barsha. They are a fantastic team of professionals with amazing creativity. The project looks spectacular, we would highly recommend it if your’re looking for a unique and stand-out interior design team.","name":"Havelock One Interiors","role":"","image":""},{"quote":"We recently had the privilege of working with TwentyOne06, and we must say, it was an exceptional experience from start to finish. They brought a level of professionalism and creativity that exceeded our expectations. Working with TwentyOne06 was an absolute pleasure! Their Professionalism, creativity, and attention to detail made our collaboration seamless and enjoyable. I highly recommend them for any design project.","name":"Lylux Lighting Group","role":"","image":""},{"quote":"Recently had the pleasure of working with TwentyOne06, and i can confidently say they are a fantastic design company. Their commitment to authenticity and quality is evident in every aspect of their work. The team is not only highly professional but also incredibly responsive, making the entire process seamless and enjoyable. From the initial consultation to final delivery, TwentyOne06 exceeded my expectations. Their innovative designs reflect a deep understanding of client needs and current trends, resulting in truly unique and impactful solutions. If you’re looking for a design partner who values excellence and creativity, I wholeheartedly recommend TwentyOne06. They are a cut above the rest.","name":"James Knight Pacheco","role":"Co-Founder/Chef/Host . the Chef JKP Podcast / Culinary Consultant","image":""},{"quote":"The process of collaborating with TwentyOne06 began with them getting to know me personally and understanding where I am coming from. They adapted to my expectations while adding their own unique design input. it was a challenge for TwentyOne06 because many restaurant designers tend to replicate designs, but they didn’t. instead, they transformed the design into what it is today, which is commendable.","name":"Reif Othman","role":"Owner . Hotaru Holdings","image":""},{"quote":"It was a true pleasure working with TwentyOne06. Govind and his team have successfully combined our vision with their expertise and experienceto come up not only with an innovative design but most importantly a functional space whilst maximizing our resources. throughout the entire design process, TwentyOne06’s attention to detail was second to none. They were professional, flexible and understood every facet of what we wanted to capture in great detail","name":"Kishore Sathar","role":"General manager . Dusit Thani Hotel","image":""},{"quote":"As a seasoned F&B operator I’ve had the pleasure to have worked with the best in class pertaining to design specialists. 2106 in my opinion would be considered as best in class.... Govind and his team have demonstrated the ability to understand our vision and interpreted this in to reality. Its also worth mentioning that their ability to adapt to change is commendable and their ability to manage the appointed contractor is substantiated with depth of knowledge in materials and market trends as well as keeping our “the Client” interest at the forefront of the projects 2106 have managed for Sarood Hospitality. On behalf of Sarood I would like to thank Govind and the 2106 team for their services conducted to help drive Flow and The Noodle House Brands.","name":"Steven Holloway","role":"Contractors Direct . CEO","image":""},{"quote":"TwentyOne06 was the visionary force behind Reif & Tero, meticulously designing an extraordinary culinary haven that offers diners an unparalleled gastronomic experience. Light Link worked tirelessly with the team at TwentyOne06, to create 2 very different styles of dining experience for Reif Othman in the new Dubai Hills location, and WE LOVE IT! From taking initial sketches and samples of tea brushes through to truly bespoke light fittings, custom neon pendants, and wall sconces all dreamt up in the mind of Govind Shepley and the team, were brought to life by our designers and custom partners.","name":"David Cook","role":"Contractors Direct . CEO","image":""},{"quote":"Working with Govind and Studio TwentyOne06 has eased the processes between the client, contractor and design team alike. The clear and detailed design has aided us to execute the design intent and deliver to the agreed timetable. It’s a credit to their design teams’ understanding of the client’s business requirements, knowledge of the F&B industry and more importantly in sourcing local finishes to stay in line with Capex budget is certainly music to our ears! We’re always glad to work alongside Studio TwentyOne06 projects.","name":"Esam Bacoush","role":"Associate Director . Dif Interiors","image":""},{"quote":"I had the pleasure of working with Govind Shepley, Mike, Hannah, Sabiha and Satinder on Voco Monaco Lobby renovation and ELIX Spa. TwentyOne06’s creativity, hard work, passion and patience is truly inspiring on all project portfolios we collaborate on. Well done to you all!","name":"Marwa Sharaky","role":"Senior Design Manager . Kleindienst Group (Voco Monaco, Elix Spa)","image":""},{"quote":"What an amazing concept this is! It is such a pleasure collaborating with such a talented team like TwentyOne06 on this project. Massive congrats on taking home the Highly Commended award.","name":"Pierre Engelbrecht","role":"associate . Compass project Consulting","image":""},{"quote":"TwentyOne06 was the visionary force behind Reif & Tero, meticulously designing an extraordinary culinary haven that offers diners an unparalleled gastronomic experience. Light Link worked tirelessly with the team at TwentyOne06, to create 2 very different styles of dining experience for Reif Othman in the new Dubai Hills location, and WE LOVE IT! From taking initial sketches and samples of tea brushes through to truly bespoke light fittings, custom neon pendants, and wall sconces all dreamt up in the mind of Govind Shepley and the team, were brought to life by our designers and custom partners.","name":"Light Link","role":"","image":""}],"contact":{"title":"Let’s Talk!","ctaTitle":["Let’s Create Something","Extraordinary."],"ctaButton":"Start a Project","ctaTo":"/contact","formTitle":"Send a Message","submit":"Send Your Brief","fields":[{"id":"name","label":"Name","type":"text","placeholder":"Your name","required":true},{"id":"email","label":"Email","type":"email","placeholder":"Info@twentyone06.com","required":true},{"id":"phone","label":"Phone","type":"tel","placeholder":"50 000 0000","required":false},{"id":"interest","label":"Project Type","type":"select","placeholder":"Select a focus","required":true,"options":["Interior Design","Branding","Design Management","Design Strategy and Operations"]},{"id":"message","label":"Message","type":"textarea","placeholder":"Tell us about your project…","required":true}],"details":[{"label":"Email","value":"info@twentyone06.com","href":"mailto:info@twentyone06.com"},{"label":"Phone","value":"04 554 8082","href":"tel:+97145548082"},{"label":"Studio","value":"Al Maktab, Office 304, 23rd St, Al Barsha First, Al Barsha, Dubai"}],"social":[{"label":"Facebook","href":"https://www.facebook.com/p/TwentyOne06-100054351738420/"},{"label":"Instagram","href":"https://www.instagram.com/twentyone06/"},{"label":"Linkedin","href":"https://www.linkedin.com/company/twentyone06"}],"copyright":"© 2026 TwentyOne06. All rights reserved."},"eyebrow":"Creative Design Studio","title":["Design by the People.","For the People."],"description":"Dubai''s multi-award winning\ninterior design and branding studio.","body_html":"<p>Every space we design starts with a question: what does this need to do for the people using it? Not aesthetically. Commercially. Experientially. Operationally. In hospitality, F&amp;B, and retail, the design is not decoration. It is the reason guests stay longer, come back, and bring others. We design with that understanding at the centre of every brief, bold where it counts, precise where it matters, and always in service of the people the space is built for.</p>"}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('85393031-20ba-428e-a3e8-c2846014cd80', 'about', 'About', '{"storyTitle":["It Started in Apartment 2106.","It Hasn''t Stopped Since."],"story":["In 2018, Govind Shepley turned apartment 2106 into the starting point for what would become one of the most recognised full-service interior design studios in Dubai and across the UAE. What began with a single project and one clear conviction, that great design starts with people, has since grown into a multi-award winning studio trusted by Michelin-starred chefs, international hotel groups, and leading retail brands across the region.","TwentyOne06 now operates across four integrated service lines, Interior Design, Branding, Design Project Management, and Design Strategy and Operations, covering the full arc of a project from the very first brief to handover, and in many cases, well beyond it."],"recognition":"Govind''s recognition among the 50 Masters of Design 2026 is proof that the industry has noticed. Not just for the work, but for how he leads, through trust, authenticity, and an unwavering commitment to raising the standard of design across the Middle East.","recognitionCredits":"50 Masters of Design 2026  ·  CID Power 50 (2021, 2022)  ·  Design Middle East Powerlist Creative 30 (2022, 2024, 2025)  ·  Design Middle East Cover, January 2025","cta":"Let Us Design Your Story","team":{"eyebrow":"The Studio","title":"Our Team","description":"The people behind the work."},"milestones":{"title":["Milestones We''re","Proud Of."],"body":"We have spent 7 years doing the work that earns the numbers, not the other way around. We don''t measure success in square metres. We measure it in spaces that open on time, clients who come back, and awards that prove the work speaks for itself.","stats":[{"value":40,"suffix":"+","label":"Successful Projects"},{"value":60,"suffix":"+","label":"Clients Served"},{"value":38,"suffix":"+","label":"Award Nominations"}]},"workTogether":{"title":["Got a project","in mind?"],"body":"Tell us about it. We''ll take it from there.","cta":"Let''s Talk","ctaTo":"/contact"},"eyebrow":"The Studio","title":["About Us"],"description":"It Started in Apartment 2106. It Hasn''t Stopped Since.","body_html":"<p>In 2018, Govind Shepley turned apartment 2106 into the starting point for what would become one of the most recognised full-service interior design studios in Dubai and across the UAE. What began with a single project and one clear conviction, that great design starts with people, has since grown into a multi-award winning studio trusted by Michelin-starred chefs, international hotel groups, and leading retail brands across the region.</p><p>TwentyOne06 now operates across four integrated service lines, Interior Design, Branding, Design Project Management, and Design Strategy and Operations, covering the full arc of a project from the very first brief to handover, and in many cases, well beyond it.</p>","seo":{"title":"About TwentyOne06, Full-Service Interior Design Firm, Dubai","description":"TwentyOne06 is a multi-award winning interior design and branding firm in Dubai. Founded by Govind Shepley, 50 Masters of Design 2026. Serving hospitality, F&B, hotels, retail, and commercial clients across the UAE and GCC.","keywords":["interior design studio Dubai","about TwentyOne06","Govind Shepley interior design","full-service design studio UAE","hospitality design firm Dubai"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('b577ad3b-5c8f-4606-af0b-fbb11fab6f93', 'contact', 'Contact', '{"body":"You''ve seen what we do. Now let''s talk about what we can do for you. Whether you have a finished brief or just an idea. Share it with us and we''ll take it from there.","map":{"title":"TwentyOne06, Interior Design & Branding","embedUrl":"https://maps.google.com/maps?q=TwentyOne06%20-%20Interior%20Design%20%26%20Branding&t=m&z=16&output=embed&iwloc=near","linkUrl":"https://www.google.com/maps/place/TwentyOne06/@25.113307,55.202634,16z/data=!4m6!3m5!1s0x65e0eb0b9615dd27:0xb05789dd21b237ae!8m2!3d25.1133073!4d55.2026337!16s%2Fg%2F11vjmqd6tl"},"details":[{"label":"Visit","lines":["Al Maktab, Office 304","23rd St, Al Barsha First","Al Barsha, Dubai"]},{"label":"Call","lines":["04 554 8082"],"href":"tel:+97145548082"},{"label":"Email","lines":["info@twentyone06.com"],"href":"mailto:info@twentyone06.com"},{"label":"Studio Hours","lines":["Mon - Fri · 9:00 - 18:00","Sat by appointment"]}],"form":{"fields":[{"id":"firstName","label":"First Name","type":"text","placeholder":"First name","required":true},{"id":"lastName","label":"Last Name","type":"text","placeholder":"Last name","required":true},{"id":"email","label":"Email Address","type":"email","placeholder":"Info@twentyone06.com","required":true},{"id":"phone","label":"Phone Number","type":"tel","placeholder":"50 000 0000","required":false},{"id":"company","label":"Company / Restaurant Name","type":"text","placeholder":"Your company or venue","required":true},{"id":"industry","label":"Industry","type":"select","placeholder":"Select industry","required":true,"options":["Hospitality","F&B","Hotels","Retail","Commercial","Other"]},{"id":"serviceEnquiry","label":"Service Enquiry","type":"select","placeholder":"Select a service","required":true,"options":["Interior Design","Branding","Design Management","Design Strategy and Operations","Not Sure Yet","All of the Above"]},{"id":"message","label":"Tell us about your project","type":"textarea","placeholder":"Share as much or as little as you like. We''ll take it from there.","required":true}],"submit":"Send Your Brief","note":"By submitting, you agree to be contacted by TwentyOne06 regarding your inquiry. We never share your details.","thankYouEmail":{"subject":"Thank You for Getting in Touch","body":["Hello,","","Thank you for reaching out to TwentyOne06, Interior and Branding Design Firm.","Every great project starts with a conversation, and we''re excited to learn more about yours.","","We''ve received your submission and will be in touch shortly.","In the meantime, feel free to explore our latest projects and insights.","","We look forward to learning more about your vision.","","Warm regards,","The TwentyOne06 Team"]}},"eyebrow":"Get in Touch","title":["Let’s Talk!"],"description":"We design spaces for people.\nLet''s start with yours.","body_html":"<p>You''ve seen what we do. Now let''s talk about what we can do for you. Whether you have a finished brief or just an idea. Share it with us and we''ll take it from there.</p>","seo":{"title":"Let''s Talk, TwentyOne06","description":"We design spaces for people. Let''s start with yours. Share your brief with TwentyOne06, interior design, branding, design management, and strategy across Dubai and the GCC.","keywords":["contact TwentyOne06","interior design studio Dubai contact","hospitality design enquiry Dubai"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('80fd954c-99c5-4f2b-a1a1-56826bbbdbbb', 'services', 'Services', '{"contact":{"title":"Let’s Talk!","eyebrow":"We design spaces for people. Let''s start with yours.","body":"You''ve seen what we do. Now let''s talk about what we can do for you. Whether you have a finished brief or just an idea. Share it with us and we''ll take it from there."},"eyebrow":"Services","title":["Where Vision","Meets Craft"],"description":"The studio behind Dubai''s most talked-about hospitality and F&B spaces, from the first brief to the final handover, and everything in between.","body_html":"<h2>Interior Design</h2><p>TwentyOne06 is a multi-award winning interior design firm in Dubai, specialising in hospitality, F&amp;B, hotel, retail, and commercial spaces.</p><p>40+ projects across Dubai, the UAE, and the GCC, from Michelin-starred restaurants to international hotel groups. We cover every stage, every sector, and every detail from the first brief to the final handover.</p>\n<h2>Branding</h2><p>Your space tells a story, and we make sure it tells the right one. We develop branding strategies that extend from logos and signage to environmental graphics and wayfinding systems, giving every touchpoint a consistent, distinctive voice.</p>\n<h2>Design Management</h2><p>Excellence in execution requires meticulous oversight. We add local market expertise to your team, connecting client, designer, and contractor under one clear direction, and bringing the leadership and accountability your project needs to be delivered without compromising on quality or creativity.</p>\n<h2>Design Strategy &amp; Operations</h2><p>Before a single line is drawn, the most important decisions are already being made. TwentyOne06''s Design Strategy and Operations service helps hospitality and F&amp;B operators across Dubai, the UAE, and the GCC, define what their space needs to achieve, commercially, experientially, and operationally, before the design process begins. From space programming and guest experience mapping to revenue-driven design frameworks, we ensure creative ambition and business reality stay aligned from day one.</p>","seo":{"title":"TwentyOne06 Services | Interior Design, Branding, Design Management & Strategy, Dubai","description":"TwentyOne06 offers 4 integrated design services, Interior Design, Branding, Design Management, and Design Strategy and Operations, across hospitality, F&B, hotels, retail, and commercial spaces in Dubai, the UAE, Saudi Arabia, and Kuwait.","keywords":["interior design services Dubai","branding studio Dubai","design management UAE","design strategy hospitality Dubai","full-service design studio GCC","hospitality interior design firm Dubai","F&B interior design UAE","hotel interior design Dubai","retail interior design GCC","commercial design firm Dubai"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('0b12c075-4417-4f87-af38-be1b17c3b48e', 'projects', 'Projects', '{"philosophy":{"eyebrow":"The Approach","title":["Our","Philosophy"],"quote":"Every space tells a story before a single word is spoken.","body":"We design spaces that work as hard as they look. Across hospitality, F&B, hotels, retail, and commercial projects in Dubai and the UAE, we have earned the trust of leading hotel groups, Michelin-starred chefs, and major retail brands. Not by following the brief, but by understanding the people behind it. Every space we design is built to shape how guests feel, how long they stay, and whether they come back."},"eyebrow":"Full-Service Design Studio, Dubai","title":["Crafting Spaces","Built For People"],"description":"From Michelin-starred restaurants to international hotel groups, every space designed to perform, not just to impress.","body_html":"<p>We design spaces that work as hard as they look. Across hospitality, F&amp;B, hotels, retail, and commercial projects in Dubai and the UAE, we have earned the trust of leading hotel groups, Michelin-starred chefs, and major retail brands. Not by following the brief, but by understanding the people behind it. Every space we design is built to shape how guests feel, how long they stay, and whether they come back.</p>","seo":{"title":"TwentyOne06 Projects | Full-Service Interior Design Studio, Dubai","description":"Explore 40+ interior design and branding projects by TwentyOne06, Dubai''s multi-award winning full-service design studio. Hospitality, F&B, hotels, retail, and commercial spaces across the UAE and GCC.","keywords":["interior design projects Dubai","hospitality design portfolio UAE","F&B interior design Dubai","hotel design UAE","commercial interior design GCC","branding studio portfolio Dubai"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
