INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('55dffa21-cd28-43b6-af94-eaa29269d521', 'faq', 'FAQ', '{"eyebrow":"Help Center","title":["Answers Crafted","With Clarity"],"description":"Everything you need to know about working with TwentyOne06, from who we are and what we design, to services, timelines, and how to get started.","body_html":"","seo":{"title":"FAQs TwentyOne06 | Interior and Branding Design Firm, Dubai","description":"Answers to the most common questions about TwentyOne06, Dubai''s multi-award winning interior design and branding studio. Interior Design, Branding, Design Project Management, and Design Strategy across the UAE, Saudi Arabia, and Kuwait.","keywords":["interior design studio Dubai FAQ","hospitality interior design questions UAE","branding studio Dubai","design project management UAE","full-service design studio GCC","how to start interior design project Dubai","interior design cost Dubai","TwentyOne06 services"]}}'::jsonb, true)
