INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('5c2f1573-5422-4d9d-a1f4-a97865a56b30', 'privacy', 'Privacy Policy', '{"sections":[{"id":"introduction","title":"Introduction","paragraphs":["TwentyOne06 is committed to protecting your privacy. This Privacy Policy explains how we collect, use, store, share, and protect your personal data when you visit www.twentyone06.com or engage with our services, and outlines your rights under UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (''UAE PDPL''). If you have any questions, please contact us at info@twentyone06.com."]},{"id":"who-we-are","title":"Who We Are","paragraphs":["The data controller responsible for your personal data is TWENTYONE ZERO SIX PROJECT MANAGEMENT, operating under the trading name TwentyOne06, registered in Dubai, United Arab Emirates."],"showAddress":true},{"id":"what-we-collect","title":"What Personal Data We Collect","paragraphs":["We collect personal data when you interact with us. This includes information you provide directly, such as your name, email address, phone number, company name, and project details submitted through our contact forms or by email. When you browse our website, we also collect technical data automatically through cookies and analytics tools, including your IP address, browser type, device information, and pages visited. We may also receive information if you interact with our content on Facebook, Instagram, or LinkedIn. We do not collect sensitive personal data, such as health, biometric, financial, religious, or political information, unless specifically required and with your explicit consent."]},{"id":"how-we-use","title":"How We Use Your Personal Data","paragraphs":["We use your personal data to respond to your enquiries and discuss potential projects; to manage and deliver our services to clients; to improve our website using anonymised analytics; and to send marketing communications where you have given your consent. You may withdraw your consent for marketing at any time by contacting us at info@twentyone06.com. We also process data where required to comply with applicable UAE law. We do not use your personal data for automated decision-making or profiling."]},{"id":"who-we-share","title":"Who We Share Your Data With","paragraphs":["TwentyOne06 does not sell, rent, or trade your personal data. We may share it with trusted service providers who support our business operations, such as hosting providers, email platforms, and analytics tools, who are bound to process your data only in accordance with our instructions. We may also share data with professional advisors or with law enforcement and regulatory authorities where required by law. In the event of a business transfer, your data may be transferred to the relevant third party under the same obligations as set out in this policy."]},{"id":"retention","title":"How Long We Keep Your Data","paragraphs":["We retain your personal data only for as long as necessary. Enquiry data is kept for up to two years from your last contact with us. Client project data is kept for up to seven years following project completion, in line with UAE commercial requirements. Data processed on the basis of consent is kept until you withdraw that consent. Website analytics data is retained in anonymised form for up to 24 months. When no longer needed, your data will be securely deleted or anonymised."]},{"id":"your-rights","title":"Your Rights","paragraphs":["Under the UAE PDPL, you have the right to access, correct, delete, restrict, or object to the processing of your personal data, and to request a portable copy of your data. To exercise any of these rights, please contact us at info@twentyone06.com. We will respond within 30 days of receipt. Where a request is particularly complex, we may extend this by a further 30 days and will notify you accordingly."]},{"id":"cookies","title":"Cookies","paragraphs":["Our website uses cookies to improve your browsing experience and analyse traffic. Essential cookies are required for the Website to function. Analytics cookies are used on an anonymised basis. Marketing cookies are only placed with your explicit consent. You can manage your cookie preferences through your browser settings at any time."]},{"id":"security","title":"Data Security","paragraphs":["TwentyOne06 takes the security of your personal data seriously and implements appropriate technical and organisational measures to protect it against unauthorised access, loss, or disclosure. While we take all reasonable steps to safeguard your data, no electronic transmission or storage is entirely secure. In the event of a data breach, we will notify the UAE Data Office and affected individuals as required by the UAE PDPL."]},{"id":"third-party","title":"Third-Party Websites","paragraphs":["Our website may link to third-party websites. We are not responsible for their privacy practices and encourage you to review their policies before sharing any personal data with them."]},{"id":"changes","title":"Changes to This Policy","paragraphs":["We may update this Privacy Policy from time to time. The date of the most recent update is shown at the top of this page. We encourage you to review it periodically."]},{"id":"contact","title":"Contact and Complaints","paragraphs":["For questions about this Privacy Policy or to exercise your data rights, please contact us:"],"showAddress":true}],"controller":{"name":"TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06'')","lines":["Al Maktab, Office 304, 23rd Street","Al Barsha First, Al Barsha, Dubai","United Arab Emirates"],"phone":"+971 4 554 8082","phoneHref":"tel:+97145548082","email":"info@twentyone06.com","web":"www.twentyone06.com","webHref":"https://www.twentyone06.com"},"image":null,"eyebrow":"Legal","title":["Privacy","Policy"],"description":"How we collect, use, and protect your personal data when you visit our website or engage with TwentyOne06.","body_html":"<h2>Introduction</h2><p>TwentyOne06 is committed to protecting your privacy. This Privacy Policy explains how we collect, use, store, share, and protect your personal data when you visit www.twentyone06.com or engage with our services, and outlines your rights under UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (''UAE PDPL''). If you have any questions, please contact us at info@twentyone06.com.</p>\n<h2>Who We Are</h2><p>The data controller responsible for your personal data is TWENTYONE ZERO SIX PROJECT MANAGEMENT, operating under the trading name TwentyOne06, registered in Dubai, United Arab Emirates.</p>\n<h2>What Personal Data We Collect</h2><p>We collect personal data when you interact with us. This includes information you provide directly, such as your name, email address, phone number, company name, and project details submitted through our contact forms or by email. When you browse our website, we also collect technical data automatically through cookies and analytics tools, including your IP address, browser type, device information, and pages visited. We may also receive information if you interact with our content on Facebook, Instagram, or LinkedIn. We do not collect sensitive personal data, such as health, biometric, financial, religious, or political information, unless specifically required and with your explicit consent.</p>\n<h2>How We Use Your Personal Data</h2><p>We use your personal data to respond to your enquiries and discuss potential projects; to manage and deliver our services to clients; to improve our website using anonymised analytics; and to send marketing communications where you have given your consent. You may withdraw your consent for marketing at any time by contacting us at info@twentyone06.com. We also process data where required to comply with applicable UAE law. We do not use your personal data for automated decision-making or profiling.</p>\n<h2>Who We Share Your Data With</h2><p>TwentyOne06 does not sell, rent, or trade your personal data. We may share it with trusted service providers who support our business operations, such as hosting providers, email platforms, and analytics tools, who are bound to process your data only in accordance with our instructions. We may also share data with professional advisors or with law enforcement and regulatory authorities where required by law. In the event of a business transfer, your data may be transferred to the relevant third party under the same obligations as set out in this policy.</p>\n<h2>How Long We Keep Your Data</h2><p>We retain your personal data only for as long as necessary. Enquiry data is kept for up to two years from your last contact with us. Client project data is kept for up to seven years following project completion, in line with UAE commercial requirements. Data processed on the basis of consent is kept until you withdraw that consent. Website analytics data is retained in anonymised form for up to 24 months. When no longer needed, your data will be securely deleted or anonymised.</p>\n<h2>Your Rights</h2><p>Under the UAE PDPL, you have the right to access, correct, delete, restrict, or object to the processing of your personal data, and to request a portable copy of your data. To exercise any of these rights, please contact us at info@twentyone06.com. We will respond within 30 days of receipt. Where a request is particularly complex, we may extend this by a further 30 days and will notify you accordingly.</p>\n<h2>Cookies</h2><p>Our website uses cookies to improve your browsing experience and analyse traffic. Essential cookies are required for the Website to function. Analytics cookies are used on an anonymised basis. Marketing cookies are only placed with your explicit consent. You can manage your cookie preferences through your browser settings at any time.</p>\n<h2>Data Security</h2><p>TwentyOne06 takes the security of your personal data seriously and implements appropriate technical and organisational measures to protect it against unauthorised access, loss, or disclosure. While we take all reasonable steps to safeguard your data, no electronic transmission or storage is entirely secure. In the event of a data breach, we will notify the UAE Data Office and affected individuals as required by the UAE PDPL.</p>\n<h2>Third-Party Websites</h2><p>Our website may link to third-party websites. We are not responsible for their privacy practices and encourage you to review their policies before sharing any personal data with them.</p>\n<h2>Changes to This Policy</h2><p>We may update this Privacy Policy from time to time. The date of the most recent update is shown at the top of this page. We encourage you to review it periodically.</p>\n<h2>Contact and Complaints</h2><p>For questions about this Privacy Policy or to exercise your data rights, please contact us:</p>","seo":{"title":"Privacy Policy, Twentyone06","description":"How TwentyOne06 collects, uses, and protects your personal data under the UAE PDPL.","keywords":["TwentyOne06 privacy policy","UAE PDPL","interior design studio Dubai privacy"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('7dee4cc2-0d35-48e8-ae3d-a6a4b37bc09c', 'terms', 'Terms and Conditions', '{"sections":[{"id":"introduction","title":"1. Introduction","paragraphs":["Welcome to www.twentyone06.com (''Website''), operated by TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06''), a full-service interior design and branding studio registered in Dubai, United Arab Emirates under Trade License No. 813936, issued by the Department of Economy and Tourism, Dubai. By accessing or using this Website, you agree to be bound by these Terms and Conditions (''Terms''). If you do not agree to these Terms, please do not continue to use this Website. We reserve the right to amend these Terms at any time, and your continued use of the Website following any amendment constitutes your acceptance of the revised Terms."]},{"id":"intellectual-property","title":"2. Intellectual Property","paragraphs":["All content published on this Website, including text, project photography, design concepts, graphics, logos, and branding, is the intellectual property of TwentyOne06 or is used with the express permission of the respective rights holders. All such rights are reserved. You may view and print pages from this Website for personal, non-commercial use only, provided that all copyright notices remain intact. Reproduction, distribution, modification, or commercial use of any content without the prior written consent of TwentyOne06 is strictly prohibited."]},{"id":"use-of-website","title":"3. Use of This Website","paragraphs":["You agree to use this Website only for lawful purposes and in a manner that does not infringe the rights of any third party. You must not use this Website to transmit unsolicited commercial communications, introduce malicious software, attempt to gain unauthorised access to any part of the Website or its systems, copy or extract content without permission, or violate any applicable local, national, or international law or regulation."]},{"id":"enquiries","title":"4. Enquiries and Services","paragraphs":["Information about TwentyOne06''s services on this Website is provided for general information only and does not constitute a binding offer or contract. Submitting an enquiry through our contact form or by email does not create a contractual relationship between you and TwentyOne06. All project engagements are subject to a separate written agreement between TwentyOne06 and the client."]},{"id":"liability","title":"5. Disclaimers and Limitation of Liability","paragraphs":["The content on this Website is provided in good faith and for general information only. TwentyOne06 makes no warranties, express or implied, regarding the accuracy, completeness, or fitness for purpose of any information on this Website. To the fullest extent permitted by applicable UAE law, TWENTYONE ZERO SIX PROJECT MANAGEMENT shall not be liable for any loss or damage, whether direct, indirect, incidental, or consequential, arising from your use of or reliance on this Website or its content, or from your inability to access the Website. We do not warrant that the Website will be uninterrupted, error-free, or free from viruses or other harmful components."]},{"id":"third-party-links","title":"6. Third-Party Links","paragraphs":["This Website may contain links to third-party websites for your convenience. TwentyOne06 has no control over the content of those websites and accepts no responsibility for them or for any loss or damage that may arise from your use of them. The inclusion of any link does not imply endorsement by TwentyOne06."]},{"id":"privacy","title":"7. Privacy and Data Protection","paragraphs":["Your use of this Website is governed by our Privacy Policy, which is incorporated into these Terms by reference. Please review our Privacy Policy to understand how we collect, use, and protect your information."],"link":{"label":"Privacy Policy","to":"/privacy"}},{"id":"severability","title":"8. Severability","paragraphs":["If any provision of these Terms is found to be invalid, unlawful, or unenforceable, that provision shall be modified or removed to the minimum extent necessary. The remaining provisions shall continue in full force and effect."]},{"id":"governing-law","title":"9. Governing Law","paragraphs":["These Terms and Conditions shall be governed by and construed in accordance with the laws of the United Arab Emirates, as applied in the Emirate of Dubai. Any disputes shall be subject to the exclusive jurisdiction of the courts of Dubai, UAE."]},{"id":"changes","title":"10. Changes to These Terms","paragraphs":["TwentyOne06 reserves the right to revise these Terms at any time. The date of the most recent revision is shown at the top of this page. Your continued use of the Website following any changes constitutes your acceptance of the revised Terms."]},{"id":"contact","title":"11. Contact Us","paragraphs":["If you have any questions regarding these Terms and Conditions, please contact us:"],"showAddress":true}],"controller":{"name":"TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06'')","lines":["Al Maktab, Office 304, 23rd Street","Al Barsha First, Al Barsha, Dubai","United Arab Emirates"],"phone":"+971 4 554 8082","phoneHref":"tel:+97145548082","email":"info@twentyone06.com","web":"www.twentyone06.com","webHref":"https://www.twentyone06.com"},"image":null,"eyebrow":"Legal","title":["Terms and","Conditions"],"description":"The terms that govern your use of the TwentyOne06 website and how we engage with enquiries and services.","body_html":"<h2>1. Introduction</h2><p>Welcome to www.twentyone06.com (''Website''), operated by TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06''), a full-service interior design and branding studio registered in Dubai, United Arab Emirates under Trade License No. 813936, issued by the Department of Economy and Tourism, Dubai. By accessing or using this Website, you agree to be bound by these Terms and Conditions (''Terms''). If you do not agree to these Terms, please do not continue to use this Website. We reserve the right to amend these Terms at any time, and your continued use of the Website following any amendment constitutes your acceptance of the revised Terms.</p>\n<h2>2. Intellectual Property</h2><p>All content published on this Website, including text, project photography, design concepts, graphics, logos, and branding, is the intellectual property of TwentyOne06 or is used with the express permission of the respective rights holders. All such rights are reserved. You may view and print pages from this Website for personal, non-commercial use only, provided that all copyright notices remain intact. Reproduction, distribution, modification, or commercial use of any content without the prior written consent of TwentyOne06 is strictly prohibited.</p>\n<h2>3. Use of This Website</h2><p>You agree to use this Website only for lawful purposes and in a manner that does not infringe the rights of any third party. You must not use this Website to transmit unsolicited commercial communications, introduce malicious software, attempt to gain unauthorised access to any part of the Website or its systems, copy or extract content without permission, or violate any applicable local, national, or international law or regulation.</p>\n<h2>4. Enquiries and Services</h2><p>Information about TwentyOne06''s services on this Website is provided for general information only and does not constitute a binding offer or contract. Submitting an enquiry through our contact form or by email does not create a contractual relationship between you and TwentyOne06. All project engagements are subject to a separate written agreement between TwentyOne06 and the client.</p>\n<h2>5. Disclaimers and Limitation of Liability</h2><p>The content on this Website is provided in good faith and for general information only. TwentyOne06 makes no warranties, express or implied, regarding the accuracy, completeness, or fitness for purpose of any information on this Website. To the fullest extent permitted by applicable UAE law, TWENTYONE ZERO SIX PROJECT MANAGEMENT shall not be liable for any loss or damage, whether direct, indirect, incidental, or consequential, arising from your use of or reliance on this Website or its content, or from your inability to access the Website. We do not warrant that the Website will be uninterrupted, error-free, or free from viruses or other harmful components.</p>\n<h2>6. Third-Party Links</h2><p>This Website may contain links to third-party websites for your convenience. TwentyOne06 has no control over the content of those websites and accepts no responsibility for them or for any loss or damage that may arise from your use of them. The inclusion of any link does not imply endorsement by TwentyOne06.</p>\n<h2>7. Privacy and Data Protection</h2><p>Your use of this Website is governed by our Privacy Policy, which is incorporated into these Terms by reference. Please review our Privacy Policy to understand how we collect, use, and protect your information.</p>\n<h2>8. Severability</h2><p>If any provision of these Terms is found to be invalid, unlawful, or unenforceable, that provision shall be modified or removed to the minimum extent necessary. The remaining provisions shall continue in full force and effect.</p>\n<h2>9. Governing Law</h2><p>These Terms and Conditions shall be governed by and construed in accordance with the laws of the United Arab Emirates, as applied in the Emirate of Dubai. Any disputes shall be subject to the exclusive jurisdiction of the courts of Dubai, UAE.</p>\n<h2>10. Changes to These Terms</h2><p>TwentyOne06 reserves the right to revise these Terms at any time. The date of the most recent revision is shown at the top of this page. Your continued use of the Website following any changes constitutes your acceptance of the revised Terms.</p>\n<h2>11. Contact Us</h2><p>If you have any questions regarding these Terms and Conditions, please contact us:</p>","seo":{"title":"Terms and Conditions, Twentyone06","description":"Terms governing use of the TwentyOne06 website, enquiries, and related services.","keywords":["TwentyOne06 terms","interior design studio Dubai terms"]}}'::jsonb, true)
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      published = EXCLUDED.published,
      updated_at = now();
INSERT INTO public.marketing_pages (id, slug, title, content, published)
